import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import os

def plot_ensemble_feature_importance(model_engine, preprocessor, numerical_cols, categorical_cols):
    """
    Extracts column headers from the transformer pipeline and plots 
    the top structural drivers of customer attrition.
    """
    # 1. Extract dynamic column names generated by OneHotEncoder
    cat_encoder = preprocessor.named_transformers_['cat'].named_steps['encoder']
    encoded_cat_cols = list(cat_encoder.get_feature_names_out(categorical_cols))

    # Recombine all features in the exact order they left the pipeline
    all_feature_names = numerical_cols + encoded_cat_cols

    # 2. Extract importances from the underlying XGBoost model in the ensemble
    xgb_estimator = model_engine.named_estimators_['xgb']
    importances = xgb_estimator.feature_importances_

    # Map features to their respective importance scores
    importance_df = pd.DataFrame({
        'Feature': all_feature_names,
        'Importance': importances
    }).sort_values(by='Importance', ascending=False).head(12) # Take top 12 drivers

    # 3. Construct Visual Plot
    plt.figure(figsize=(10, 6))
    sns.barplot(data=importance_df, x='Importance', y='Feature', palette='viridis')
    plt.title("Top 12 Operational Drivers of Customer Attrition")
    plt.xlabel("Relative Feature Importance Score")
    plt.ylabel("Operational Feature")

    os.makedirs("outputs", exist_ok=True)
    plt.savefig("outputs/feature_importance.png", bbox_inches='tight')
    plt.close()
    print(" Feature importance plot exported to: outputs/feature_importance.png")